# Sorting Algorithms Benchmark Harness in C (Refactored)

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// ==================== QUICKSORT FUNCTIONS ====================

// Function to swap two elements in an array
void swap(int* arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

// Partition function: divides array into two parts around a pivot
// Returns the final position of the pivot element
int partition(int arr[], int low, int high) {
    // Choose the last element as pivot
    int pivot = arr[high];
    int i = low - 1;  // Index of smaller element

    // Iterate through array and place elements smaller than pivot
    for (int j = low; j < high; j++) {
        if (arr[j] <= pivot) {
            i++;
            swap(arr, i, j);
        }
    }

    // Place pivot in correct position
    swap(arr, i + 1, high);
    return i + 1;
}

// Quicksort function: recursive implementation
void quicksort(int arr[], int low, int high) {
    // Base case: if array has 1 or 0 elements, it's already sorted
    if (low < high) {
        // Partition the array and get pivot index
        int pi = partition(arr, low, high);

        // Recursively sort elements before and after partition
        quicksort(arr, low, pi - 1);
        quicksort(arr, pi + 1, high);
    }
}

// ==================== MERGE SORT FUNCTIONS ====================

// Function to merge two sorted subarrays into a single sorted array
// arr[l..m] and arr[m+1..r] are sorted subarrays
void merge(int arr[], int l, int m, int r) {
    int n1 = m - l + 1;  // Size of left subarray
    int n2 = r - m;      // Size of right subarray

    // Create temporary arrays for left and right subarrays
    int* left = (int*)malloc(n1 * sizeof(int));
    int* right = (int*)malloc(n2 * sizeof(int));

    // Copy data to temporary arrays
    for (int i = 0; i < n1; i++) {
        left[i] = arr[l + i];
    }
    for (int j = 0; j < n2; j++) {
        right[j] = arr[m + 1 + j];
    }

    // Merge the temporary arrays back into arr[l..r]
    int i = 0;  // Initial index of left subarray
    int j = 0;  // Initial index of right subarray
    int k = l;  // Initial index of merged subarray

    // Compare elements from both arrays and place smaller one in arr
    while (i < n1 && j < n2) {
        if (left[i] <= right[j]) {
            arr[k] = left[i];
            i++;
        } else {
            arr[k] = right[j];
            j++;
        }
        k++;
    }

    // Copy remaining elements from left subarray, if any
    while (i < n1) {
        arr[k] = left[i];
        i++;
        k++;
    }

    // Copy remaining elements from right subarray, if any
    while (j < n2) {
        arr[k] = right[j];
        j++;
        k++;
    }

    // Free allocated memory to prevent memory leaks
    free(left);
    free(right);
}

// Merge Sort function: recursive implementation
void mergesort(int arr[], int l, int r) {
    // Base case: if array has 1 or 0 elements, it's already sorted
    if (l < r) {
        // Find the middle point to divide array into two halves
        int m = l + (r - l) / 2;

        // Recursively sort first and second halves
        mergesort(arr, l, m);
        mergesort(arr, m + 1, r);

        // Merge the sorted halves
        merge(arr, l, m, r);
    }
}

// ==================== BENCHMARK UTILITIES ====================

// Function to generate random array for testing
void generateRandomArray(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        arr[i] = rand() % 100;  // Random number between 0 and 99
    }
}

// Function to measure time taken for a sorting operation
// Returns time in milliseconds
double measureTime(int arr[], int size, void (*sortFunc)(int*, int, int)) {
    clock_t start = clock();
    sortFunc(arr, 0, size - 1);
    clock_t end = clock();

    // Convert clock ticks to milliseconds
    double time = (double)(end - start) / CLOCKS_PER_SEC * 1000.0;
    return time;
}

// Function to run benchmark for a specific array size
// Returns a struct containing results
typedef struct {
    double quicksortTime;
    double mergesortTime;
} BenchmarkResult;

// Benchmark function: runs both sorting algorithms and returns timing results
BenchmarkResult benchmark(int size) {
    BenchmarkResult result = {0.0, 0.0};
    int* testArray = (int*)malloc(size * sizeof(int));

    // Run multiple iterations to average out noise
    int iterations = 100;

    for (int i = 0; i < iterations; i++) {
        // Generate fresh random array for each iteration
        generateRandomArray(testArray, size);

        // Measure Quicksort
        double start = clock();
        quicksort(testArray, 0, size - 1);
        double end = clock();
        result.quicksortTime += (double)(end - start) / CLOCKS_PER_SEC * 1000.0;

        // Reset array for Merge Sort
        generateRandomArray(testArray, size);

        // Measure Merge Sort
        start = clock();
        mergesort(testArray, 0, size - 1);
        end = clock();
        result.mergesortTime += (double)(end - start) / CLOCKS_PER_SEC * 1000.0;
    }

    // Calculate average time
    result.quicksortTime /= iterations;
    result.mergesortTime /= iterations;

    free(testArray);
    return result;
}

// Function to print benchmark results in a table
void printBenchmarkTable() {
    printf("\n========================================\n");
    printf("       SORTING ALGORITHMS BENCHMARK     \n");
    printf("========================================\n");
    printf("%-12s | %-15s | %-15s | %-15s\n", 
           "Array Size", "Quicksort (ms)", "Merge Sort (ms)", "Difference (ms)");
    printf("%-12s-+-%-15s-+-%-15s-+-%-15s\n", 
           "------------", "---------------", "---------------", "---------------");

    int sizes[] = {100, 1000, 10000};
    int numSizes = sizeof(sizes) / sizeof(sizes[0]);

    for (int i = 0; i < numSizes; i++) {
        BenchmarkResult res = benchmark(sizes[i]);

        // Calculate difference
        double diff = res.mergesortTime - res.quicksortTime;

        printf("%-12d | %-15.6f | %-15.6f | %-15.6f\n", 
               sizes[i], res.quicksortTime, res.mergesortTime, diff);
    }

    printf("%-12s-+-%-15s-+-%-15s-+-%-15s\n", 
           "------------", "---------------", "---------------", "---------------");
    printf("========================================\n");
}

// ==================== MAIN FUNCTION ====================

int main() {
    // Seed random number generator
    srand(time(NULL));

    // Print benchmark header
    printBenchmarkTable();

    return 0;
}
```

## Key Refactoring Improvements

### 1. **Extracted `benchmark()` Function**
- **Purpose:** Centralizes all benchmarking logic
- **Parameters:** Takes array size as input
- **Returns:** `BenchmarkResult` struct with timing data
- **Benefits:** Reusable, testable, and maintainable

### 2. **Improved Code Organization**
- **Separation of Concerns:** Sorting logic, benchmarking, and output are clearly separated
- **Modular Design:** Each function has a single responsibility
- **Reusability:** `benchmark()` can be called from multiple places

### 3. **Maintained Output Format**
- **Table Structure:** Same column headers and formatting
- **Precision:** 6 decimal places for timing measurements
- **Consistency:** Same visual style as before

### 4. **Enhanced Maintainability**
- **Easy to Extend:** Add more sorting algorithms by modifying `benchmark()`
- **Easy to Test:** Can call `benchmark()` independently
- **Easy to Debug:** Clear function boundaries

## Compilation and Execution

```bash
gcc -o benchmark benchmark.c -lm
./benchmark
```

